import{_ as t,o,c as a,ag as i}from"./chunks/framework.XeSgnAkN.js";const h=JSON.parse('{"title":"App Store Review Notes Template","description":"","frontmatter":{},"headers":[],"relativePath":"appstore-review-notes.md","filePath":"appstore-review-notes.md","lastUpdated":1791284224000}'),s={name:"appstore-review-notes.md"};function n(l,e,r,d,p,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="app-store-review-notes-template" tabindex="-1">App Store Review Notes Template <a class="header-anchor" href="#app-store-review-notes-template" aria-label="Permalink to &quot;App Store Review Notes Template&quot;">​</a></h1><p>Use this text (adapt as needed) in the App Review notes section.</p><p>Pigeon is a local-first macOS menu bar capture app.</p><ul><li>The app runs in the menu bar and opens a spotlight-style capture panel with a global shortcut.</li><li>Captured entries are written to user-selected local markdown files.</li><li>On first setup, the user chooses a folder via the system folder picker.</li><li>The app does not require an account for its core features and does not download executable code.</li><li>App Store build does not include in-app update flow. Updates are handled by the Mac App Store.</li></ul><h2 id="pigeon-cloud-optional-sign-in" tabindex="-1">Pigeon Cloud (optional sign-in) <a class="header-anchor" href="#pigeon-cloud-optional-sign-in" aria-label="Permalink to &quot;Pigeon Cloud (optional sign-in)&quot;">​</a></h2><p>Add this when the build includes Pigeon Cloud. Replace the placeholders with the values set as the server&#39;s <code>APP_REVIEW_EMAIL</code> and <code>APP_REVIEW_CODE</code> secrets. Put the code only in App Store Connect, never in this repository.</p><ul><li>Pigeon Cloud is optional. It syncs the user&#39;s tasks and lets AI assistants the user connects (for example Claude) read and add tasks.</li><li>To try it: Settings → Pigeon Cloud → Connect → Continue with email. <ul><li>Email: <code>&lt;review email&gt;</code></li><li>Code: <code>&lt;six-digit review code&gt;</code> (no email is sent to this address)</li></ul></li><li>Account deletion: Settings → Pigeon Cloud → Delete account… permanently deletes the account and its cloud data.</li></ul>',7)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
